  selectBatchBar(label: string): void {
    const normalizedLabel = label.toLocaleLowerCase();
    const rows = this.rows.filter((row) => String(row['Tags'] ?? '').split(';').some((tag) => {
      const normalized = tag.trim().toLocaleLowerCase();
      if (normalizedLabel === 'pilot') return /^pilot(?: case)?$/i.test(normalized);
      if (normalizedLabel === 'hospitals') return /^hospitals?$/i.test(normalized);
      return normalized.replace(/[\s_-]/g, '') === normalizedLabel.replace(/[\s_-]/g, '');
    }));
    this.selectDashboardBar(`${label} cases`, rows);
  }

  get siteIdChart(): SiteIdItem[] {
    const counts = this.rows.reduce<Record<string, number>>((result, row) => {
      const siteId = String(row['Site ID'] ?? '').trim();
      if (!siteId) return result;
      result[siteId] = (result[siteId] ?? 0) + 1;
      return result;
    }, {});
    const entries = Object.entries(counts).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, 10);
    const width = Math.max(640, 104 + entries.length * 72);
    const slotWidth = (width - 104) / Math.max(1, entries.length);
    const maximum = Math.max(1, ...entries.map(([, count]) => count));
    const axisMaximum = Math.ceil(maximum / 4) * 4;
    const chartHeight = 150;
    return entries.map(([label, count], index) => {
      const x = 72 + (index + 0.5) * slotWidth;
      const rectHeight = (count / axisMaximum) * chartHeight;
      const hasAllowedTag = this.rows.some((row) => {
        if (String(row['Site ID'] ?? '').trim() !== label) return false;
        return this.hasSiteIdBarTag(row['Tags']);
      });
      return { label, count, x, y: 182 - rectHeight, rectX: x - Math.min(30, slotWidth * .62) / 2, rectY: 182 - rectHeight, rectWidth: Math.min(30, slotWidth * .62), rectHeight, color: hasAllowedTag ? '#86b894' : '#a7aea8' };
    });
  }

  private hasSiteIdBarTag(value: unknown): boolean {
    return String(value ?? '').split(';').some((tag) => {
      const normalized = tag.trim().toLocaleLowerCase();
      return normalized === 'pilot case'
        || normalized === 'hospitals'
        || /^batch[\s_-]*\d+$/.test(normalized);
    });
  }

  get siteIdChartWidth(): number { return Math.max(640, 104 + this.siteIdChart.length * 72); }
  get siteIdChartAxisRight(): number { return this.siteIdChartWidth - 28; }
  get siteIdChartTicks(): ChartTick[] {
    const maximum = Math.max(1, ...this.siteIdChart.map((item) => item.count));
    const axisMaximum = Math.ceil(maximum / 4) * 4;
    return Array.from({ length: 5 }, (_, index) => ({ value: axisMaximum - index * axisMaximum / 4, y: 32 + index * 150 / 4 }));
  }
  get caseCategoryChart(): CaseCategoryItem[] {
    const categories = [
      { label: 'Datasync', matches: ['datasync'] },
      { label: 'Codefix', matches: ['devfixrequired', 'codefix', 'code fix'] },
      { label: 'Feature', matches: ['feature', 'access related'] },
      { label: 'No Fix', matches: ['validation', 'no fix', 'nofix'] },
      { label: 'Analysis', matches: ['analysis case'] },
    ];
    const categoryRows = categories.map(({ matches }) => this.rows.filter((row) => {
      const tags = String(row['Tags'] ?? '').split(';').map((tag) => tag.trim().toLocaleLowerCase());
      return tags.some((tag) => matches.includes(tag) || (matches.includes('feature') && tag.includes('feature')));
    }));
    const counts = categoryRows.map((rows) => rows.length);
    const width = 640;
    const slotWidth = (width - 104) / categories.length;
    const axisMaximum = Math.ceil(Math.max(1, ...counts) / 4) * 4;
    const chartHeight = 150;
    return categories.map(({ label }, index) => {
      const count = counts[index];
      const x = 72 + (index + 0.5) * slotWidth;
      const rectHeight = (count / axisMaximum) * chartHeight;
      const rectWidth = Math.min(64, slotWidth * .62);
      const hasUnonboardedValidation = label === 'No Fix' && categoryRows[index].some((row) => !String(row['Tags'] ?? '').split(';').some((tag) => /^batch[\s_-]*\d+$/i.test(tag.trim())));
      return { label, count, x, y: 182 - rectHeight, rectX: x - rectWidth / 2, rectY: 182 - rectHeight, rectWidth, rectHeight, color: hasUnonboardedValidation ? '#a7aea8' : '#6f9f7d' };
    });
  }
  get caseCategoryChartTotal(): number { return this.caseCategoryChart.reduce((sum, item) => sum + item.count, 0); }
  get caseCategoryChartTicks(): ChartTick[] {
    const maximum = Math.max(1, ...this.caseCategoryChart.map((item) => item.count));
    const axisMaximum = Math.ceil(maximum / 4) * 4;
    return Array.from({ length: 5 }, (_, index) => ({ value: axisMaximum - index * axisMaximum / 4, y: 32 + index * 150 / 4 }));
  }
  hoveredRolloutPoint: string | null = null;
